1	<script lang="ts">
2		import { supabase } from '$lib/supabaseClient';
3		import { onMount } from 'svelte';
4		import { page } from '$app/stores';
5		import { goto } from '$app/navigation';
6		import { resolve } from '$app/paths';
7	
8		let email = '';
9		let password = '';
10		let loading = false;
11		let errorMsg: string | null = null;
12		let successMsg: string | null = null;
13	
14		async function login(e: Event) {
15			e.preventDefault();
16			errorMsg = null;
17			loading = true;
18			const { data, error } = await supabase.auth.signInWithPassword({ email, password });
19			loading = false;
20			if (error) {
21				errorMsg = error.message || 'Login failed. Please check your email and password.';
22				return;
23			}
24			if (data.session) {
25				// Use SvelteKit navigation instead of full page reload
26				// This allows auth state change events to propagate properly
27				await goto(resolve('/receipts'), { replaceState: true });
28			}
29		}
30	
31		onMount(async () => {
32			const sess = await supabase.auth.getSession();
33			if (sess.data.session) {
34				await goto(resolve('/receipts'), { replaceState: true });
35			}
36	
37			// Check for password reset success message
38			const params = new URLSearchParams(window.location.search);
39			if (params.get('reset') === 'success') {
40				successMsg = 'Password reset successful! Please log in with your new password.';
41			}
42		});
43	</script>
44	
