49		{/if}
50		{#if successMsg}
51			<div class="mb-3 rounded border border-green-200 bg-green-50 p-2 text-green-700">
52				{successMsg}
53			</div>
54		{/if}
55		<form onsubmit={login} class="space-y-3">
56			<div>
57				<label class="block text-sm font-medium">Email</label>
58				<input
59					required
60					type="email"
61					class="mt-1 w-full rounded border px-3 py-2"
62					bind:value={email}
63				/>
64			</div>
65			<div>
66				<label class="block text-sm font-medium">Password</label>
67				<input
68					required
69					type="password"
70					class="mt-1 w-full rounded border px-3 py-2"
71					bind:value={password}
72				/>
73			</div>
74			<div class="text-right">
75				<a href={resolve('/forgot-password')} class="text-sm text-blue-600 hover:underline">
76					Forgot password?
77				</a>
78			</div>
79			<button
80				class="w-full rounded bg-blue-600 py-2 text-white disabled:opacity-50"
81				disabled={loading}>{loading ? 'Signing in…' : 'Sign in'}</button
82			>
83		</form>
84	</div>
