1	<script lang="ts">
2		import { supabase } from '$lib/supabaseClient';
3		import {
4			validatePassword,
5			passwordsMatch,
6			MIN_LENGTH_MESSAGE,
7			CHAR_TYPE_MESSAGE
8		} from '$lib/utils/passwordValidation';
9		import { onMount } from 'svelte';
10		import { goto } from '$app/navigation';
11		import { resolve } from '$app/paths';
12	
13		let password = $state('');
14		let confirmPassword = $state('');
15		let loading = $state(false);
16		let errorMsg: string | null = $state(null);
17		let showPassword = $state(false);
18		let showConfirmPassword = $state(false);
19	
20		let validation = $derived(validatePassword(password));
21		let passwordMatch = $derived(passwordsMatch(password, confirmPassword));
22		let canSubmit = $derived(validation.isValid && passwordMatch && !loading);
23	
24		onMount(async () => {
25			// Check if we have a valid session from the recovery link
26			const {
27				data: { session },
28				error
29			} = await supabase.auth.getSession();
30	
31			// If no session or not a recovery session, redirect to forgot-password
32			if (error || !session) {
33				errorMsg = 'This password reset link is invalid. Please request a new one.';
34				setTimeout(() => goto(resolve('/forgot-password')), 3000);
35			}
36		});
37	
38		async function handleSubmit(e: Event) {
39			e.preventDefault();
40	
41			if (!canSubmit) return;
42	
43			errorMsg = null;
44			loading = true;
45	
46			try {
47				const { error } = await supabase.auth.updateUser({
48					password: password
49				});
50	
51				loading = false;
52	
53				if (error) {
54					if (error.message.includes('expired')) {
55						errorMsg = 'This password reset link has expired. Please request a new one.';
56						setTimeout(() => goto(resolve('/forgot-password')), 3000);
57					} else if (error.message.includes('weak') || error.message.includes('password')) {
58						errorMsg = 'Password does not meet security requirements.';
59					} else {
60						errorMsg = error.message || 'Unable to reset password. Please try again.';
61					}
62					return;
63				}
64	
65				// Success - redirect to login with success message
66				goto(resolve('/login?reset=success'));
67			} catch (err) {
68				loading = false;
69				errorMsg = 'Unable to reset password. Please check your connection and try again.';
70				console.error('Password reset exception:', err);
71			}
72		}
73	</script>
74	
