77	
78		<p class="mb-4 text-sm text-gray-600">Enter your new password below.</p>
79	
80		{#if errorMsg}
81			<div class="mb-3 rounded border border-red-200 bg-red-50 p-2 text-red-700">{errorMsg}</div>
82		{/if}
83	
84		<form onsubmit={handleSubmit} class="space-y-3">
85			<div>
86				<label class="block text-sm font-medium">New Password</label>
87				<div class="relative mt-1">
88					<input
89						required
90						type={showPassword ? 'text' : 'password'}
91						class="w-full rounded border px-3 py-2 pr-10"
92						bind:value={password}
93					/>
94					<button
95						type="button"
96						class="absolute top-2 right-2 text-gray-500 hover:text-gray-700"
97						onclick={() => (showPassword = !showPassword)}
98					>
99						{showPassword ? '👁️' : '👁️‍🗨️'}
100					</button>
101				</div>
102			</div>
103	
104			<div>
105				<label class="block text-sm font-medium">Confirm Password</label>
106				<div class="relative mt-1">
107					<input
108						required
109						type={showConfirmPassword ? 'text' : 'password'}
110						class="w-full rounded border px-3 py-2 pr-10"
111						bind:value={confirmPassword}
112					/>
113					<button
114						type="button"
115						class="absolute top-2 right-2 text-gray-500 hover:text-gray-700"
116						onclick={() => (showConfirmPassword = !showConfirmPassword)}
117					>
118						{showConfirmPassword ? '👁️' : '👁️‍🗨️'}
119					</button>
120				</div>
121			</div>
122	
123			<!-- Password Requirements Checklist -->
124			<div class="rounded border border-gray-200 bg-gray-50 p-3">
125				<p class="mb-2 text-xs font-medium text-gray-700">Password Requirements:</p>
126				<ul class="space-y-1 text-xs">
127					<li class="flex items-center gap-2">
128						<span class={validation.checks.minLength ? 'text-green-600' : 'text-gray-400'}>
129							{validation.checks.minLength ? '✓' : '✗'}
130						</span>
131						<span class={validation.checks.minLength ? 'text-green-600' : 'text-gray-600'}>
132							{MIN_LENGTH_MESSAGE}
133						</span>
134					</li>
135					<li class="flex items-center gap-2">
136						<span class={validation.checks.hasCharacterType ? 'text-green-600' : 'text-gray-400'}>
137							{validation.checks.hasCharacterType ? '✓' : '✗'}
138						</span>
139						<span class={validation.checks.hasCharacterType ? 'text-green-600' : 'text-gray-600'}>
140							{CHAR_TYPE_MESSAGE}
141						</span>
142					</li>
143					{#if confirmPassword.length > 0}
144						<li class="flex items-center gap-2">
145							<span class={passwordMatch ? 'text-green-600' : 'text-gray-400'}>
146								{passwordMatch ? '✓' : '✗'}
147							</span>
148							<span class={passwordMatch ? 'text-green-600' : 'text-gray-600'}>
149								Passwords match
150							</span>
151						</li>
152					{/if}
153				</ul>
154			</div>
155	
156			<button
157				class="w-full rounded bg-blue-600 py-2 text-white disabled:opacity-50"
158				disabled={!canSubmit}
159			>
160				{loading ? 'Resetting Password...' : 'Reset Password'}
161			</button>
162		</form>
163	
164		<div class="mt-4 text-center">
165			<a href={resolve('/forgot-password')} class="text-sm text-blue-600 hover:underline">
166				Request new reset link
167			</a>
168		</div>
169	</div>
