11		import { untrack } from 'svelte';
12	
13		/**
14		 * Receipt Edit Modal Component
15		 *
16		 * Specification: specs/specifications/receipt-edit-modal.md
17		 *
18		 * This component provides a unified interface for editing receipts across
19		 * both the Receipts tab and Reconciliation tab. It supports:
20		 * - Viewing receipt images with zoom and pan (#{#zom1a} - #{#zom5b})
21		 * - Editing all receipt fields
22		 * - Saving receipts with empty/null fields (OCR may fail)
23		 * - Keyboard navigation and accessibility
24		 */
25	
26		interface Props {
27			receipt: ReceiptRow;
28			show?: boolean;
29			isSaving?: boolean;
30			error?: string | null;
31			currentCategory?: Category | null;
32			categories?: Category[];
33			familyId?: string;
34			onclose?: () => void;
35			onsave?: (receipt: ReceiptRow) => void;
36			onCategoryChange?: (receiptId: string, category: Category) => void;
37		}
38	
39		let {
40			receipt,
41			show = false,
42			isSaving = false,
43			error = $bindable(null),
44			currentCategory = null,
45			categories,
46			familyId,
47			onclose,
48			onsave,
49			onCategoryChange
50		}: Props = $props();
51	
52		// #{#rct1b} Local copy of receipt for editing (don't mutate prop).
53		// untrack: intentionally seed the local copy from the prop's initial value only.
54		let editedReceipt: ReceiptRow = $state(untrack(() => ({ ...receipt })));
55		let receiptImageUrl: string | null = $state(null);
56	
57		// #{#rmc1a} Local category selection — saved only on Save.
58		// untrack: seed from the prop's initial value; later changes are user-driven.
59		let selectedCategory: Category | null = $state(untrack(() => currentCategory ?? null));
60	
61		// #{#pdf1a} Detect if receipt is a PDF
62		let receiptIsPdf = $derived(isPdfFile(receipt.receipt_image_path));
63	
64		// #{#rim1a} and #{#zom1a} Floating image viewer modal state
65		let showImageViewer = $state(false);
66	
67		// #{#rct7b} #{#rmc1a} Dirty checking — compare edited receipt and selectedCategory against originals
68		let isDirty = $derived(
69			editedReceipt.merchant_name !== receipt.merchant_name ||
70				editedReceipt.transaction_date !== receipt.transaction_date ||
71				editedReceipt.total_amount !== receipt.total_amount ||
72				editedReceipt.tax !== receipt.tax ||
73				editedReceipt.currency !== receipt.currency ||
74				editedReceipt.credit_card_name !== receipt.credit_card_name ||
75				editedReceipt.credit_card_last_4 !== receipt.credit_card_last_4 ||
76				selectedCategory?.id !== currentCategory?.id
77		);
78	
79		// #{#rct7b} Discard confirmation dialog state
80		let showDiscardConfirm = $state(false);
81	
82		// #{#rct2a} #{#sec1a} Load signed receipt image URL when component mounts or receipt changes
83		$effect(() => {
84			if (receipt.receipt_image_path) {
85				getSignedReceiptUrl(receipt.receipt_image_path).then((url) => {
86					receiptImageUrl = url;
87				});
88			} else {
89				receiptImageUrl = null;
90			}
91		});
92	
93		// #{#rct1b} Reset edited receipt and category when receipt prop changes
94		$effect(() => {
95			editedReceipt = { ...receipt };
96			selectedCategory = currentCategory ?? null;
97		});
98	
99		// #{#rct4b} Close modal (internal — always closes)
100		function close() {
101			showDiscardConfirm = false;
102			onclose?.();
103		}
104	
105		// #{#rct7b} Close with dirty check — warns if unsaved changes exist
106		function requestClose() {
107			if (isDirty) {
108				showDiscardConfirm = true;
109			} else {
110				close();
111			}
112		}
113	
114		// #{#rct7b} Confirm discard — user chose to lose changes
115		function confirmDiscard() {
116			showDiscardConfirm = false;
117			onclose?.();
118		}
119	
120		// #{#rct7b} Cancel discard — user chose to keep editing
121		function cancelDiscard() {
122			showDiscardConfirm = false;
123		}
124	
125		// #{#rct5a} Save changes
126		async function save() {
127			// #{#rct3a} Validate minimum data requirement
128			const hasMinimumData =
129				(editedReceipt.merchant_name && editedReceipt.merchant_name.trim() !== '') ||
130				editedReceipt.total_amount !== null ||
131				(editedReceipt.transaction_date && editedReceipt.transaction_date.trim() !== '');
132	
133			if (!hasMinimumData) {
134				// Set local error (will be displayed in modal)
135				error = 'Receipt must have at least a merchant name, amount, or date';
136				return;
137			}
138	
139			// Clear any previous errors
140			error = null;
141	
142			// #{#rmc1a} If category changed, notify parent to persist
143			if (selectedCategory && selectedCategory.id !== currentCategory?.id) {
144				onCategoryChange?.(editedReceipt.id, selectedCategory);
145			}
146	
147			// #{#fcr1a} #{#fcr2a} Fetch exchange rate if currency is foreign and changed or date changed
148			const isForeignCurrency = editedReceipt.currency && editedReceipt.currency !== 'CAD';
149			const currencyChanged = editedReceipt.currency !== receipt.currency;
150			const dateChanged = editedReceipt.transaction_date !== receipt.transaction_date;
151			const missingRate =
152				editedReceipt.exchange_rate_to_cad === null ||
153				editedReceipt.exchange_rate_to_cad === undefined;
154	
155			if (
156				isForeignCurrency &&
157				(currencyChanged || dateChanged || missingRate) &&
158				editedReceipt.transaction_date
159			) {
160				const rate = await ExchangeRateService.fetchRate(
161					editedReceipt.currency!,
162					editedReceipt.transaction_date
163				);
164				editedReceipt.exchange_rate_to_cad = rate;
165			} else if (!isForeignCurrency) {
166				editedReceipt.exchange_rate_to_cad = null;
167			}
168	
169			// Emit save event with edited data
170			onsave?.(editedReceipt);
171		}
172	
173		// #{#rct4b} #{#rct7b} Handle backdrop click — uses requestClose for dirty check
174		function handleBackdropClick(e: MouseEvent) {
175			if (e.target === e.currentTarget) {
176				requestClose();
177			}
178		}
179	
180		// #{#rct4b} #{#rct7b} Handle keyboard events — uses requestClose for dirty check
181		function handleKeydown(e: KeyboardEvent) {
182			if (e.key === 'Escape') {
183				requestClose();
184			}
185		}
186	
187		// #{#rim1a} and #{#zom1a} Open floating image viewer
188		function openImageViewer() {
189			showImageViewer = true;
190		}
191	
