86		/**
87		 * #{#zom1a} Zoom to a specific level, optionally anchored at a cursor position.
88		 * The point under the cursor stays fixed on screen after zoom.
89		 */
90		function zoomTo(newZoom: number, cursorX?: number, cursorY?: number) {
91			const container = scrollContainer;
92			newZoom = Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, newZoom));
93	
94			if (!container || baseWidth === 0) {
95				zoom = newZoom;
96				return;
97			}
98	
99			const oldZoom = zoom;
100			if (newZoom === oldZoom) return;
101	
102			const rect = container.getBoundingClientRect();
103			// Default to center of viewport if no cursor position given
104			const cx = cursorX !== undefined ? cursorX - rect.left : rect.width / 2;
105			const cy = cursorY !== undefined ? cursorY - rect.top : rect.height / 2;
106	
107			// Point in base-image coordinates under the cursor
108			const imageX = (container.scrollLeft + cx) / (oldZoom / 100);
109			const imageY = (container.scrollTop + cy) / (oldZoom / 100);
110	
111			zoom = newZoom;
112	
113			// After Svelte updates the DOM (image resizes), adjust scroll so the
114			// same image point remains under the cursor.
115			const targetScrollLeft = imageX * (newZoom / 100) - cx;
116			const targetScrollTop = imageY * (newZoom / 100) - cy;
117			cancelAnimationFrame(rafId);
118			rafId = requestAnimationFrame(() => {
119				if (container) {
120					container.scrollLeft = targetScrollLeft;
121					container.scrollTop = targetScrollTop;
122				}
123			});
124		}
125	
126		/**
127		 * #{#zom1a} Zoom in by one step (snaps to 50% increments)
128		 */
129		function zoomIn(cursorX?: number, cursorY?: number) {
130			zoomTo(Math.ceil((zoom + 1) / ZOOM_STEP) * ZOOM_STEP, cursorX, cursorY);
131		}
132	
133		/**
134		 * #{#zom1a} Zoom out by one step (snaps to 50% increments)
135		 */
136		function zoomOut(cursorX?: number, cursorY?: number) {
137			zoomTo(Math.floor((zoom - 1) / ZOOM_STEP) * ZOOM_STEP, cursorX, cursorY);
138		}
139	
140		/**
141		 * #{#zom1a} Reset zoom to 100% and scroll to origin
142		 */
143		function resetZoom() {
144			zoom = MIN_ZOOM;
145			if (scrollContainer) {
146				scrollContainer.scrollLeft = 0;
147				scrollContainer.scrollTop = 0;
148			}
149		}
150	
151		/**
152		 * #{#zom1b} #{#pdf1c} Handle mouse wheel zoom — disabled for PDFs.
153		 * Zooms toward the cursor position.
154		 */
155		function handleWheel(e: WheelEvent) {
156			if (isPdf) return; // #{#pdf1c} Let browser PDF viewer handle scroll
157			e.preventDefault();
158			if (e.deltaY < 0) {
159				zoomIn(e.clientX, e.clientY);
160			} else {
161				zoomOut(e.clientX, e.clientY);
162			}
163		}
164	
165		/**
166		 * #{#zom2a} #{#pdf1c} Handle mouse down to start drag-scrolling — disabled for PDFs
167		 */
168		function handleMouseDown(e: MouseEvent) {
169			if (isPdf) return; // #{#pdf1c}
170			if (zoom > MIN_ZOOM) {
171				isDragging = true;
172				dragStartX = e.clientX;
173				dragStartY = e.clientY;
174				scrollStartX = scrollContainer?.scrollLeft ?? 0;
175				scrollStartY = scrollContainer?.scrollTop ?? 0;
176				e.preventDefault();
177			}
178		}
179	
180		/**
181		 * #{#zom2a} Handle mouse move for drag-scrolling
182		 */
183		function handleMouseMove(e: MouseEvent) {
184			if (isDragging && scrollContainer) {
185				scrollContainer.scrollLeft = scrollStartX - (e.clientX - dragStartX);
186				scrollContainer.scrollTop = scrollStartY - (e.clientY - dragStartY);
187			}
188		}
189	
190		/**
191		 * #{#zom2a} Handle mouse up to stop drag-scrolling
192		 */
193		function handleMouseUp() {
194			isDragging = false;
195		}
196	
197		/**
198		 * #{#zom2b} #{#zom5a} #{#pdf1c} Handle keyboard navigation — zoom/pan disabled for PDFs
199		 */
200		function handleKeydown(e: KeyboardEvent) {
201			// Only handle keyboard shortcuts when the image viewer is open
202			if (!show) return;
203	
204			// Escape key closes modal - #{#zom5a} — works for both images and PDFs
205			if (e.key === 'Escape') {
206				close();
207				return;
208			}
209	
210			// #{#pdf1c} Skip zoom/pan keyboard shortcuts for PDFs
211			if (isPdf) return;
212	
213			// Arrow keys for scrolling when zoomed - #{#zom2b}
214			if (zoom > MIN_ZOOM && scrollContainer) {
215				switch (e.key) {
216					case 'ArrowUp':
217						scrollContainer.scrollTop -= PAN_STEP;
218						e.preventDefault();
219						break;
220					case 'ArrowDown':
221						scrollContainer.scrollTop += PAN_STEP;
222						e.preventDefault();
223						break;
224					case 'ArrowLeft':
225						scrollContainer.scrollLeft -= PAN_STEP;
226						e.preventDefault();
227						break;
228					case 'ArrowRight':
229						scrollContainer.scrollLeft += PAN_STEP;
230						e.preventDefault();
231						break;
232				}
233			}
234	
235			// Optional keyboard shortcuts for zoom - #{#zom2b}
236			if (e.key === '+' || e.key === '=') {
237				zoomIn();
238				e.preventDefault();
239			} else if (e.key === '-') {
240				zoomOut();
241				e.preventDefault();
242			} else if (e.key === '0') {
243				resetZoom();
244				e.preventDefault();
245			}
246		}
247	
248		/**
249		 * #{#zom3a} Calculate distance between two touch points
250		 */
251		function getTouchDistance(e: TouchEvent): number {
252			if (e.touches.length < 2) return 0;
253			const touch1 = e.touches[0];
254			const touch2 = e.touches[1];
255			const dx = touch1.clientX - touch2.clientX;
256			const dy = touch1.clientY - touch2.clientY;
257			return Math.sqrt(dx * dx + dy * dy);
258		}
259	
260		/**
261		 * #{#zom3a} Get midpoint between two touch points
262		 */
263		function getTouchMidpoint(e: TouchEvent): { x: number; y: number } {
264			return {
265				x: (e.touches[0].clientX + e.touches[1].clientX) / 2,
266				y: (e.touches[0].clientY + e.touches[1].clientY) / 2
267			};
268		}
269	
270		/**
271		 * #{#zom3a} #{#pdf1c} Handle touch start for pinch zoom and pan — disabled for PDFs
272		 */
273		function handleTouchStart(e: TouchEvent) {
274			if (isPdf) return; // #{#pdf1c}
275			if (e.touches.length === 2) {
276				// Pinch zoom start
277				touchStartDistance = getTouchDistance(e);
278				touchStartZoom = zoom;
279				e.preventDefault();
280			} else if (e.touches.length === 1) {
281				// Check for double tap - #{#zom3a}
282				const now = Date.now();
283				if (now - lastTapTime < DOUBLE_TAP_DELAY) {
284					// Double tap detected — zoom toward tap point
285					if (zoom === MIN_ZOOM) {
286						zoomTo(200, e.touches[0].clientX, e.touches[0].clientY);
287					} else {
288						resetZoom();
289					}
290					e.preventDefault();
291				}
292				lastTapTime = now;
293	
294				// Single touch drag-scroll (if zoomed)
295				if (zoom > MIN_ZOOM) {
296					isDragging = true;
297					dragStartX = e.touches[0].clientX;
298					dragStartY = e.touches[0].clientY;
299					scrollStartX = scrollContainer?.scrollLeft ?? 0;
300					scrollStartY = scrollContainer?.scrollTop ?? 0;
301				}
302			}
303		}
304	
305		/**
306		 * #{#zom3a} #{#pdf1c} Handle touch move for pinch zoom and pan — disabled for PDFs
307		 */
308		function handleTouchMove(e: TouchEvent) {
309			if (isPdf) return; // #{#pdf1c}
310			if (e.touches.length === 2) {
311				// Pinch zoom — anchored at midpoint between fingers
312				const currentDistance = getTouchDistance(e);
313				const mid = getTouchMidpoint(e);
314				const newZoom = touchStartZoom * (currentDistance / touchStartDistance);
315				zoomTo(newZoom, mid.x, mid.y);
316				e.preventDefault();
317			} else if (e.touches.length === 1 && isDragging && scrollContainer) {
318				// Drag to scroll
319				scrollContainer.scrollLeft = scrollStartX - (e.touches[0].clientX - dragStartX);
320				scrollContainer.scrollTop = scrollStartY - (e.touches[0].clientY - dragStartY);
321				e.preventDefault();
322			}
323		}
324	
325		/**
326		 * #{#zom3a} Handle touch end
327		 */
328		function handleTouchEnd() {
329			isDragging = false;
330			touchStartDistance = 0;
331		}
332	
333		/**
334		 * #{#rim1b} Close the viewer
335		 */
336		function close() {
337			onclose?.();
338			resetZoom(); // #{#zom4a} Reset state when closing
339		}
340	
341		/**
342		 * #{#rim1b} Handle backdrop click
343		 */
344		function handleBackdropClick(e: MouseEvent) {
345			if (e.target === e.currentTarget) {
346				close();
347			}
348		}
349	
350		/**
351		 * #{#zom4a} Reset state when component shows
352		 */
353		$effect(() => {
354			if (show) {
355				resetZoom();
356				baseWidth = 0;
357				baseHeight = 0;
358			}
359		});
360	
361		/**
362		 * #{#zom2a} Compute cursor style based on zoom and drag state
363		 */
364		let cursorStyle = $derived(
365			zoom > MIN_ZOOM ? (isDragging ? 'grabbing' : 'grab') : 'default'
366		);
367	</script>
368	
369	<svelte:window
370		onmousemove={handleMouseMove}
371		onmouseup={handleMouseUp}
372		onkeydown={handleKeydown}
373	/>
374	
375	{#if show}
376		<!-- #{#zom5a} Modal with proper ARIA attributes -->
377		<div
378			class="fixed inset-0 z-60 flex items-center justify-center bg-black/90 p-4"
379			onclick={handleBackdropClick}
380			role="dialog"
381			aria-modal="true"
382			aria-labelledby="receipt-image-viewer-title"
383			style="touch-action: {isPdf ? 'auto' : 'none'};"
384		>
385			<!-- #{#zom5a} Screen reader title -->
386			<h2 id="receipt-image-viewer-title" class="sr-only">Receipt Image Viewer</h2>
387	
388			<!-- #{#rim1b} Close button -->
389			<button
390				onclick={close}
391				class="absolute top-4 right-4 text-white transition-colors hover:text-gray-300"
392				aria-label="Close image viewer"
393				type="button"
394			>
395				<svg class="h-8 w-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
396					<path
397						stroke-linecap="round"
398						stroke-linejoin="round"
399						stroke-width="2"
400						d="M6 18L18 6M6 6l12 12"
401					/>
402				</svg>
403			</button>
404	
405			<!-- #{#pdf1b} PDF display with white background -->
406			{#if isPdf}
407				<div
408					class="relative flex max-h-[80vh] max-w-[90vw] items-center justify-center"
409					role="document"
410					aria-label={altText}
411					tabindex="0"
412				>
413					<iframe
414						src={imageUrl}
415						title={altText}
416						class="h-[80vh] w-[90vw] rounded bg-white"
417					></iframe>
418				</div>
419			{:else}
420				<!-- Scrollable image container — replaces fixed-viewport + manual pan -->
421				<div
422					bind:this={scrollContainer}
423					class="receipt-scroll-container relative overflow-auto rounded"
424					onwheel={handleWheel}
425					onmousedown={handleMouseDown}
426					ontouchstart={handleTouchStart}
427					ontouchmove={handleTouchMove}
428					ontouchend={handleTouchEnd}
429					role="img"
430					aria-label={altText}
431					tabindex="0"
432					style={baseWidth > 0
433						? `width: ${Math.min(scaledWidth, window.innerWidth * 0.9)}px; height: ${baseHeight}px; max-width: 90vw; max-height: 80vh; cursor: ${cursorStyle};`
434						: `max-width: 90vw; max-height: 80vh; cursor: ${cursorStyle};`}
435				>
436					{#if baseWidth > 0}
437						<!-- #{#rim2a} Receipt image — sized directly for natural scroll -->
438						<img
439							src={imageUrl}
440							alt={altText}
441							class="block max-w-none select-none"
442							style="width: {scaledWidth}px; height: {scaledHeight}px;"
443							draggable="false"
444							onload={handleImageLoad}
445							onclick={(e) => e.stopPropagation()}
446						/>
447					{:else}
448						<!-- Initial render before dimensions are known -->
449						<img
450							src={imageUrl}
451							alt={altText}
452							class="block max-h-[80vh] max-w-[90vw] object-contain select-none"
453							draggable="false"
454							onload={handleImageLoad}
455							onclick={(e) => e.stopPropagation()}
456						/>
457					{/if}
458				</div>
459			{/if}
460	
461			<!-- #{#zom1a} #{#pdf1c} Zoom controls — hidden for PDFs -->
462			{#if !isPdf}
463				<div
464					class="absolute right-8 bottom-8 flex items-center gap-2 rounded-lg bg-black/70 px-4 py-2 text-white backdrop-blur-sm"
465				>
466					<!-- Zoom out button -->
467					<button
468						onclick={() => zoomOut()}
469						disabled={zoom <= MIN_ZOOM}
470						aria-label="Zoom out"
471						class="rounded p-2 transition-colors hover:bg-white/10 disabled:cursor-not-allowed disabled:opacity-30"
472						type="button"
473					>
474						<svg class="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
475							<path
476								stroke-linecap="round"
477								stroke-linejoin="round"
478								stroke-width="2"
479								d="M20 12H4"
480							/>
481						</svg>
482					</button>
483	
484					<!-- #{#zom5b} Current zoom percentage display -->
485					<span class="min-w-[3rem] text-center text-sm font-medium" aria-live="polite">
486						{Math.round(zoom)}%
487					</span>
488	
489					<!-- Zoom in button -->
490					<button
491						onclick={() => zoomIn()}
492						disabled={zoom >= MAX_ZOOM}
493						aria-label="Zoom in"
494						class="rounded p-2 transition-colors hover:bg-white/10 disabled:cursor-not-allowed disabled:opacity-30"
495						type="button"
496					>
497						<svg class="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
498							<path
499								stroke-linecap="round"
500								stroke-linejoin="round"
501								stroke-width="2"
502								d="M12 4v16m8-8H4"
503							/>
504						</svg>
505					</button>
506	
507					<!-- Divider -->
508					<div class="mx-1 h-6 w-px bg-white/30"></div>
509	
510					<!-- Reset button -->
511					<button
512						onclick={resetZoom}
513						aria-label="Reset zoom to 100%"
514						class="rounded px-3 py-1 text-sm transition-colors hover:bg-white/10"
515						type="button"
516					>
517						Reset
518					</button>
519				</div>
520			{/if}
521	
522			<!-- #{#zom5a} Screen reader announcements for zoom level changes -->
523			<div class="sr-only" aria-live="polite" aria-atomic="true">
524				{isPdf ? 'Viewing PDF receipt' : `Zoom level: ${Math.round(zoom)}%`}
525			</div>
526		</div>
527	{/if}
528	
529	<style>
530		/* #{#zom5a} Screen reader only class */
531		.sr-only {
532			position: absolute;
533			width: 1px;
534			height: 1px;
535			padding: 0;
536			margin: -1px;
537			overflow: hidden;
538			clip: rect(0, 0, 0, 0);
539			white-space: nowrap;
540			border-width: 0;
541		}
542	
543		/* Subtle scrollbars for the dark modal background */
