/**
 * #{#zom2a} #{#zom3a} Wire the pointer/wheel/touch gestures imperatively.
 *
 * These are mouse/touch *enhancements* on a natively-scrollable container, with
 * full keyboard parity provided elsewhere (global arrow/zoom/Escape shortcuts on
 * <svelte:window> and the Tab-reachable zoom buttons). There is no ARIA role that
 * accurately models a custom zoom/pan surface, so attaching the listeners via an
 * action (rather than markup `on*` handlers) keeps the element honestly
 * role-less. wheel/touchstart/touchmove are registered non-passive because the
 * handlers call preventDefault().
 */
function gestureSurface(node: HTMLElement) {
	const active = { passive: false } as AddEventListenerOptions;
	node.addEventListener('wheel', handleWheel, active);
	node.addEventListener('mousedown', handleMouseDown);
	node.addEventListener('touchstart', handleTouchStart, active);
	node.addEventListener('touchmove', handleTouchMove, active);
	node.addEventListener('touchend', handleTouchEnd);
	return {
		destroy() {
			node.removeEventListener('wheel', handleWheel);
			node.removeEventListener('mousedown', handleMouseDown);
			node.removeEventListener('touchstart', handleTouchStart);
			node.removeEventListener('touchmove', handleTouchMove);
			node.removeEventListener('touchend', handleTouchEnd);
		}
	};
}

