/**
 * Converts a YYYY-MM-DD string to a Date object.
 * Returns undefined if the string is empty or invalid.
 */
export function toDate(isoString: string | null | undefined): Date | undefined {
	if (!isoString) return undefined;
	const parts = isoString.split('-');
	if (parts.length !== 3) return undefined;
	const year = parseInt(parts[0], 10);
	const month = parseInt(parts[1], 10);
	const day = parseInt(parts[2], 10);
	if (isNaN(year) || isNaN(month) || isNaN(day)) return undefined;
	return new Date(year, month - 1, day);
}

/**
 * Formats a YYYY-MM-DD date string for display (e.g., "Mar 1, 2026").
 * Parses date parts manually to avoid timezone shift from new Date(string).
 */
export function formatDate(
	isoString: string | null | undefined,
	options: Intl.DateTimeFormatOptions = { year: 'numeric', month: 'short', day: 'numeric' }
): string {
	if (!isoString) return '—';
	const date = toDate(isoString);
	if (!date) return '—';
	return date.toLocaleDateString('en-US', options);
}

/**
 * Converts a Date object to a YYYY-MM-DD string.
 * Returns empty string if the date is null/undefined.
 */
export function toISODateString(date: Date | null | undefined): string {
	if (!date || isNaN(date.getTime())) return '';
	const year = date.getFullYear();
	const month = String(date.getMonth() + 1).padStart(2, '0');
	const day = String(date.getDate()).padStart(2, '0');
	return `${year}-${month}-${day}`;
}

