import { describe, it, expect } from 'vitest';
import { toDate, toISODateString, formatDate } from './dateConversion';

describe('toDate', () => {
	it('should parse YYYY-MM-DD into the correct local date', () => {
		const date = toDate('2026-03-01');
		expect(date).toBeInstanceOf(Date);
		expect(date!.getFullYear()).toBe(2026);
		expect(date!.getMonth()).toBe(2); // 0-indexed: March = 2
		expect(date!.getDate()).toBe(1);
	});

	it('should return undefined for null/undefined/empty', () => {
		expect(toDate(null)).toBeUndefined();
		expect(toDate(undefined)).toBeUndefined();
		expect(toDate('')).toBeUndefined();
	});

	it('should return undefined for invalid format', () => {
		expect(toDate('not-a-date')).toBeUndefined();
		expect(toDate('2026-13')).toBeUndefined();
	});
});

describe('toISODateString', () => {
	it('should convert a Date to YYYY-MM-DD', () => {
		const date = new Date(2026, 2, 1); // March 1, 2026
		expect(toISODateString(date)).toBe('2026-03-01');
	});

	it('should return empty string for null/undefined', () => {
		expect(toISODateString(null)).toBe('');
		expect(toISODateString(undefined)).toBe('');
	});
});

describe('formatDate', () => {
	it('should format a date string for display without timezone shift', () => {
		// This is the critical test: "2026-03-01" must display as March 1,
		// NOT February 28, regardless of the local timezone.
		const result = formatDate('2026-03-01');
		expect(result).toBe('Mar 1, 2026');
	});

	it('should preserve the correct day across month boundaries', () => {
		expect(formatDate('2026-01-01')).toBe('Jan 1, 2026');
		expect(formatDate('2025-12-31')).toBe('Dec 31, 2025');
	});

	it('should return em-dash for null/undefined/empty', () => {
		expect(formatDate(null)).toBe('—');
		expect(formatDate(undefined)).toBe('—');
		expect(formatDate('')).toBe('—');
	});

	it('should accept custom format options', () => {
		const result = formatDate('2026-03-01', {
			year: 'numeric',
			month: 'long',
			day: 'numeric'
		});
		expect(result).toBe('March 1, 2026');
	});
});

